from retry_queue import RetryQueue

def test_delay_is_capped_at_60s():
    q = RetryQueue(max_retries=10, base_delay=1.0)
    q.jobs["j1"] = {"attempts": 0, "status": "pending"}
    for _ in range(10):
        assert q.next_delay("j1") <= 60
        q.jobs["j1"]["attempts"] += 1
